import type * as React from 'react';
import type { UseOpenProps } from "../../hooks/useSelect/types.js";
import type { PopupPlacement } from "../Popup/index.js";
import type { InputControlPin, InputControlSize, InputControlView } from "../controls/index.js";
import type { AriaLabelingProps, ControlGroupOption, QAProps } from "../types.js";
import type { Option, OptionGroup } from "./tech-components.js";
export type SelectRenderClearArgs = {
    renderIcon?: () => React.ReactNode;
};
export type SelectRenderTriggerProps = AriaLabelingProps & Pick<React.ButtonHTMLAttributes<HTMLElement>, 'id' | 'type' | 'role' | 'aria-controls' | 'aria-haspopup' | 'aria-expanded' | 'aria-invalid' | 'aria-activedescendant' | 'onClick' | 'onKeyDown' | 'disabled'>;
export type SelectRenderControlProps<T extends HTMLElement = HTMLElement> = {
    onClear: () => void;
    renderClear: (args: SelectRenderClearArgs) => React.ReactNode;
    renderCounter: () => React.ReactNode;
    ref: React.Ref<T>;
    open: boolean;
    disabled?: boolean;
    triggerProps: SelectRenderTriggerProps;
};
export type SelectRenderControlOptions = {
    value: SelectProps['value'];
};
export type SelectRenderControl<T extends HTMLElement = HTMLElement> = (props: SelectRenderControlProps<T>, options: SelectRenderControlOptions) => React.ReactElement;
export type SelectRenderOptionViewParams = {
    itemHeight: number;
    isItemActive?: boolean;
};
export type SelectRenderOption<T> = (option: SelectOption<T>, options: SelectRenderOptionViewParams) => React.ReactElement;
export type SelectRenderOptionGroup<T> = (option: Pick<SelectOptionGroup<T>, 'label'>, options: SelectRenderOptionViewParams) => React.ReactElement;
export type SelectRenderPopup = (popupItems: {
    renderFilter: () => React.JSX.Element | null;
    renderList: () => React.JSX.Element;
}) => React.ReactElement;
export type SelectFilterInputProps = {
    value: string;
} & Pick<React.InputHTMLAttributes<HTMLInputElement>, 'placeholder' | 'onKeyDown' | 'onChange' | 'size' | 'aria-label' | 'aria-controls' | 'aria-activedescendant'>;
export type SelectRenderFilter = (props: {
    /** @deprecated use inputProps instead */
    onChange: (filter: string) => void;
    /** @deprecated use inputProps instead */
    onKeyDown: (e: React.KeyboardEvent<HTMLElement>) => void;
    /** @deprecated use inputProps instead */
    value: string;
    ref: React.Ref<HTMLInputElement>;
    style: React.CSSProperties;
    inputProps: SelectFilterInputProps;
}) => React.ReactElement;
export type SelectSize = InputControlSize;
export type SelectRenderCounter = (originalComponent: React.ReactElement<SelectCounterProps>, counterProps: SelectCounterProps) => React.ReactNode;
export type SelectProps<T = any> = AriaLabelingProps & QAProps & UseOpenProps & {
    onUpdate?: (value: string[]) => void;
    renderControl?: SelectRenderControl;
    renderFilter?: SelectRenderFilter;
    renderOption?: SelectRenderOption<T>;
    renderOptionGroup?: SelectRenderOptionGroup<T>;
    renderSelectedOption?: (option: SelectOption<T>, index: number) => React.ReactElement;
    renderEmptyOptions?: ({ filter }: {
        filter: string;
    }) => React.ReactElement;
    renderPopup?: SelectRenderPopup;
    renderCounter?: SelectRenderCounter;
    getOptionHeight?: (option: SelectOption<T>, index: number) => number;
    getOptionGroupHeight?: (option: SelectOptionGroup<T>, index: number) => number;
    filterOption?: (option: SelectOption<T>, filter: string) => boolean;
    view?: InputControlView;
    size?: SelectSize;
    pin?: InputControlPin;
    width?: 'auto' | 'max' | number;
    popupWidth?: 'fit' | number;
    virtualizationThreshold?: number;
    className?: string;
    controlClassName?: string;
    popupClassName?: string;
