  const [selectedLanguage, setSelectedLanguage] = useState<string[]>([language]);
  const { lang } = useLang();
  const theme = useTheme();

  const keyset = useMemo(() => i18n.keyset('app'), [lang]);

  const handleLanguageChange = (value: string[]) => {
